<script setup>
import { onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import api, { errorMessage, validationErrors } from '../../composables/useAdminApi'
import { useServerTable } from '../../composables/useServerTable'
import AdminPageHeader from '../../components/AdminPageHeader.vue'
import AdminDataTable from '../../components/AdminDataTable.vue'
import AdminPagination from '../../components/AdminPagination.vue'
import AdminStatusBadge from '../../components/AdminStatusBadge.vue'
import AdminConfirmDialog from '../../components/AdminConfirmDialog.vue'

const route=useRoute(); const router=useRouter(); const columns=[{key:'name',label:'Product',sortable:true},{key:'slug',label:'Slug',sortable:true},{key:'projects_count',label:'Projects'},{key:'active',label:'Status',sortable:true},{key:'sort_order',label:'Order',sortable:true},{key:'updated_at',label:'Updated',sortable:true}]
const {rows,meta,loading,error,state,sortBy,load}=useServerTable('/service-products',{active:'',sort:'sort_order',direction:'asc'}); const panel=ref(false); const editing=ref(null); const saving=ref(false); const errors=ref({}); const requestError=ref(''); const deactivateTarget=ref(null)
const blank=()=>({name:'',slug:'',description:'',active:true,sort_order:0}); const form=reactive(blank())
function open(item=null){if(item?.id){router.push({name:'service-products.show',params:{id:item.id}});return}editing.value=null;Object.assign(form,blank());errors.value={};requestError.value='';panel.value=true}
function close(){panel.value=false;editing.value=null;Object.assign(form,blank())}
async function save(){saving.value=true;errors.value={};try{editing.value?await api.put(`/service-products/${editing.value}`,form):await api.post('/service-products',form);close();await load()}catch(e){errors.value=validationErrors(e);requestError.value=errorMessage(e)}finally{saving.value=false}}
async function deactivate(){saving.value=true;try{await api.post(`/service-products/${deactivateTarget.value.id}/deactivate`);deactivateTarget.value=null;await load()}finally{saving.value=false}}
onMounted(()=>{if(route.query.create)open()}); watch(()=>route.query.create,value=>{if(value)open()})
</script>

<template><div class="space-y-6"><AdminPageHeader title="Service Products" eyebrow="Product register" description="Reusable services assigned to client projects."><button class="admin-button bg-dark text-light" @click="open()">New service product</button></AdminPageHeader><div class="grid gap-3 sm:grid-cols-[minmax(0,1fr)_180px]"><div class="admin-field"><label for="product-search">Search</label><input id="product-search" v-model="state.search" type="search" placeholder="Name or slug" @input="state.page=1"></div><div class="admin-field"><label for="product-active">Status</label><select id="product-active" v-model="state.active" @change="state.page=1"><option value="">All statuses</option><option value="1">Active</option><option value="0">Inactive</option></select></div></div><p v-if="error" class="text-sm text-red-700">{{error}}</p><AdminDataTable :columns="columns" :rows="rows" :loading="loading" :sort="state.sort" :direction="state.direction" empty-title="No service products yet." empty-text="Add a reusable service before creating projects." @sort="sortBy" @row-click="open"><template #cell-name="{row}"><strong>{{row.name}}</strong><small v-if="row.description" class="mt-1 block max-w-md truncate text-neutral-500">{{row.description}}</small></template><template #cell-active="{value}"><AdminStatusBadge :status="value"/></template><template #cell-updated_at="{value}">{{new Date(value).toLocaleDateString()}}</template><template #empty-action><button class="admin-button bg-dark text-light" @click="open()">Create product</button></template></AdminDataTable><AdminPagination :meta="meta" @change="page=>state.page=page"/><div v-if="panel" class="fixed inset-0 z-40 overflow-y-auto bg-dark/55 p-4" @click.self="close"><form class="ml-auto min-h-full w-full max-w-xl border border-dark bg-light p-6" @submit.prevent="save"><div class="flex items-start justify-between"><div><p class="font-mono text-xs font-bold uppercase">Service product</p><h2 class="mt-2 font-mono text-2xl font-bold">{{editing?'Edit product':'New product'}}</h2></div><button type="button" aria-label="Close" @click="close">X</button></div><p v-if="requestError" class="mt-5 text-sm text-red-700">{{requestError}}</p><div class="mt-8 space-y-5"><div class="admin-field"><label for="product-name">Name</label><input id="product-name" v-model="form.name" required><p v-if="errors.name" class="admin-error">{{errors.name[0]}}</p></div><div class="admin-field"><label for="product-slug">Slug</label><input id="product-slug" v-model="form.slug" placeholder="Generated from name when blank"><p v-if="errors.slug" class="admin-error">{{errors.slug[0]}}</p></div><div class="admin-field"><label for="product-description">Description</label><textarea id="product-description" v-model="form.description" rows="6"></textarea></div><div class="admin-field"><label for="product-order">Sort order</label><input id="product-order" v-model.number="form.sort_order" type="number" min="0" max="65535" required></div><label class="flex gap-3 border-y border-neutral-300 py-4"><input v-model="form.active" type="checkbox"><span><strong class="block text-sm">Active</strong><small class="text-neutral-500">Available for new projects</small></span></label></div><div class="mt-8 flex flex-wrap justify-between gap-3"><button v-if="editing&&form.active" type="button" class="admin-button admin-button--quiet" @click="deactivateTarget={id:editing,name:form.name}">Deactivate</button><span v-else></span><div class="flex gap-2"><button type="button" class="admin-button admin-button--quiet" @click="close">Cancel</button><button class="admin-button bg-dark text-light" :disabled="saving">{{saving?'Saving...':'Save product'}}</button></div></div></form></div><AdminConfirmDialog :open="Boolean(deactivateTarget)" title="Deactivate product?" :text="`${deactivateTarget?.name||'This product'} will remain on existing projects but cannot be selected for new ones.`" confirm-label="Deactivate" :busy="saving" @close="deactivateTarget=null" @confirm="deactivate"/></div></template>